let currentProgramId: string | null = null;
let previousProgramId: string | null = null;

export const currentContext = {
  /**
   * 进入某个 program 的上下文
   * SDK 在 program.init() / dispose() / call() 调用前调用
   */
  enter(id: string): void {
    // 防御性检查：当前实现仅支持 2 层嵌套（boundHost get + bind 回调），
    // 超过 2 层会静默丢失中间上下文。告警便于发现未来的深层嵌套 bug。
    if (previousProgramId !== null) {
      console.warn(
        `[program-host] 上下文嵌套超过 2 层: current=${String(currentProgramId)}, ` +
          `previous=${String(previousProgramId)}, entering=${id}。` +
          '当前 enter/leave 仅支持单层嵌套，多层会丢失中间上下文。',
      );
    }
    previousProgramId = currentProgramId;
    currentProgramId = id;
  },

  /**
   * 离开当前 program 上下文，恢复上一个
   */
  leave(): void {
    currentProgramId = previousProgramId;
    previousProgramId = null;
  },

  /** 获取当前活跃的 program ID */
  active(): string | null {
    return currentProgramId;
  },

  /**
   * 创建绑定闭包：在指定 program 上下文中执行
   * 用于异步回调场景（如 registerApi 的回调、setTimeout 等）
   */
  bind<T extends (...args: unknown[]) => unknown>(id: string, fn: T): T {
    return ((...args: Parameters<T>) => {
      currentContext.enter(id);
      try {
        return fn(...args);
      } finally {
        currentContext.leave();
      }
    }) as T;
  },
};
